919	/**
920	 * Full inline RCON round-trip on an already-open SSH connection: read creds from
921	 * the server's config, tunnel to 127.0.0.1:<port>, run one command. Callers guard
922	 * SANDBOX and ownership before reaching here.
923	 */
924	export async function runRcon(conn: Client, spec: GameControlSpec, command: string): Promise<RconResult> {
925	  const creds = await readRconCreds(conn, spec);
926	  if (!creds.ok) return { ok: false, error: creds.reason };
927	  let stream: Duplex;
928	  try {
929	    stream = await forwardTcp(conn, "127.0.0.1", creds.port);
930	  } catch (e) {
931	    return { ok: false, error: e instanceof Error ? e.message : "Could not open RCON channel." };
932	  }
933	  return sourceRcon(stream, creds.password, command);
934	}
