943	export type LogResult = { ok: true; lines: string[]; unit: string | null } | { ok: false; error: string };
944	
945	/**
946	 * Tail the game service's recent logs. Resolves the unit from the family hints
947	 * (compile-time constants), then reads the last `n` journal lines; if journald has
948	 * nothing, falls back to a `.log` file under the data roots. Read-only.
949	 */
950	export async function readGameLogs(conn: Client, spec: GameControlSpec, n = 200): Promise<LogResult> {
951	  const lines = Math.min(Math.max(Math.trunc(n) || 200, 20), 500);
952	  const hints = spec.serviceHints.map(shq).join(" ");
953	  const roots = spec.dataRoots.map(shq).join(" ");
954	  const script = [
955	    `unit=""`,
956	    `for c in ${hints}; do systemctl cat "$c" >/dev/null 2>&1 && { unit="$c"; break; }; done`,
957	    `if [ -z "$unit" ]; then unit=$(systemctl list-units --type=service --plain --no-legend 2>/dev/null | grep -i ${shq(spec.family)} | head -1 | awk '{print $1}'); fi`,
958	    `echo "NXLOG:UNIT:${"$"}{unit:-none}"`,
959	    `if [ -n "$unit" ]; then journalctl -u "$unit" -n ${lines} --no-pager 2>/dev/null; fi`,
960	    // Fallback: newest *.log under the data roots (bounded).
961	    `f=""; for r in ${roots}; do [ -d "$r" ] && f=$(find "$r" -maxdepth 4 -type f -name '*.log' 2>/dev/null | head -1) && [ -n "$f" ] && break; done`,
962	    `if [ -n "$f" ]; then echo "NXLOG:FILE:$f"; tail -n ${lines} "$f" 2>/dev/null; fi`,
963	  ].join("\n");
964	  const { stdout } = await exec(conn, script, QUICK_TIMEOUT_MS);
965	  const all = stdout.split(/\r?\n/);
966	  let unit: string | null = null;
967	  const out: string[] = [];
968	  for (const l of all) {
969	    const m = /^NXLOG:UNIT:(.*)$/.exec(l);
970	    if (m) {
971	      unit = m[1] === "none" ? null : m[1];
972	      continue;
973	    }
974	    if (/^NXLOG:FILE:/.test(l)) continue;
975	    out.push(l);
976	  }
977	  while (out.length && out[out.length - 1].trim() === "") out.pop();
978	  return { ok: true, lines: out.slice(-lines), unit };
979	}
