606	/**
607	 * Track player join/leave for game families with NO remote console (Valheim
608	 * today, via GAME_LOG_TRACKING in lib/game-control.ts) by tailing their own log
609	 * instead of RCON — `readGameLogs`, the exact same read-only path the Console
610	 * tab already uses. Runs every ~60s from the main loop, ALONGSIDE (not instead
611	 * of) `playerTrackingSweep` above — a server only ever matches one of the two,
612	 * since `logTrackingSpec` is only registered for families with `rcon: "none"`.
613	 *
614	 * THE REAL LIMITATION — read this before changing the inference below. Valheim's
615	 * dedicated-server log names a player on JOIN
616	 * (`Got character ZDOID from <name> : <id>`) but NOT on disconnect — a
617	 * disconnect only ever updates a running headcount (`... now N player(s)`). So
618	 * when the count drops we know FOR CERTAIN that one fewer player is connected,
619	 * but NOT which one. This sweep's handling of that gap:
620	 *
621	 *   - `onlineCount` always tracks the log's own headcount line exactly —
622	 *     ground truth, never guessed.
623	 *   - `onlineNames` (persisted on GameLogCursor) is a FIFO of names in join
624	 *     order. On a headcount decrement, the OLDEST believed-online name is
625	 *     popped and ITS PlayerSession is closed with `leftAtInferred: true` — a
626	 *     guess, not an observation, and wrong whenever the player who actually
627	 *     left isn't the longest-connected one of the group. `leftAtInferred` is
628	 *     surfaced in the UI (GamePlayerHistory) so this is never presented as
629	 *     fact.
630	 *   - If the count hits exactly 0, every remaining open session for the
631	 *     server is closed — that IS certain (nobody is connected), so those are
632	 *     NOT marked inferred.
633	 *   - If a JOIN names someone the FIFO still believes is online (drift from an
634	 *     earlier wrong guess), that stale session is closed first (inferred)
635	 *     before the fresh one opens, so drift self-corrects instead of piling up.
636	 *   - A count INCREASE with no matching join line parsed in this batch is left
637	 *     alone rather than inventing a name — `onlineCount` still updates.
638	 *
639	 * Incremental tailing: `GameLogCursor.lastLine` is the last raw line this sweep
640	 * already processed; each run only walks lines after that mark in the new tail.
641	 * `readGameLogs` is capped at the last 500 lines (lib/game-control.ts), so a
642	 * server producing >500 log lines between two ~60s sweeps could skip events —
643	 * acceptable for Valheim's actual join/leave volume, but worth knowing if this
644	 * pattern is reused for a chattier log. If the previous marker line has rolled
645	 * completely out of the new tail, this run processes nothing (rather than risk
646	 * double-counting) and just re-marks the newest line. On a server's very first
647	 * sweep (no GameLogCursor row yet) nothing is back-filled as a join — there is
648	 * no way to know when an already-connected player actually joined — so the
649	 * cursor is seeded silently and tracking starts clean from the next line on.
650	 */
651	export async function logPlayerTrackingSweep(): Promise<void> {
652	  if (SANDBOX) return;
653	
654	  const servers = await db.server.findMany({
655	    where: { status: "RUNNING", gamePlanId: { not: null } },
656	    select: CONTROL_FIELDS,
657	  });
658	
659	  for (const server of servers) {
660	    try {
661	      const fam = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
662	      if (!isGameFamily(fam)) continue;
663	      const spec = controlSpec(fam);
664	      const tracking = logTrackingSpec(fam);
665	      if (!spec || !tracking) continue; // only families with a registered log-tracking spec
666	
667	      const logRes = await withServerSsh(server as SftpServer, (conn) => readGameLogs(conn, spec, 500));
668	      if (!logRes.ok) continue;
669	      const lines = logRes.lines;
670	      if (lines.length === 0) continue;
671	
672	      const cursor = await db.gameLogCursor.findUnique({ where: { serverId: server.id } });
673	      const isFirstSweep = !cursor;
674	
675	      let startIdx = lines.length; // default: process nothing (marker missing/rolled out)
676	      if (isFirstSweep) {
677	        startIdx = lines.length; // seed only — no back-fill, see doc comment
678	      } else if (cursor!.lastLine == null) {
