import { Icon } from "@/components/nx/Icon";

/**
 * Who has been signing in to this machine.
 *
 * The `nxeon-shipper` agent has been posting SSH_LOGIN / SSH_FAILED events per
 * server into `TelemetryEvent` for some time; until now the only reader was the
 * admin monitor feed (lib/monitor-feed.ts). The customer whose server it is
 * could not see their own access log. This surfaces it, and nothing more — it
 * does not claim to be intrusion detection, and it does not score or judge the
 * events, because the data underneath is a login record, not a verdict.
 *
 * Servers without the agent installed report nothing, and that is said plainly
 * rather than drawn as an empty "0 failed logins" panel, which would read as an
 * all-clear the data cannot support.
 */

export type AccessEvent = {
  id: string;
  type: string;
  ts: string;
  ip: string | null;
  user: string | null;
};

const KIND: Record<string, { label: string; icon: string; ink: string; ring: string }> = {
  SSH_LOGIN:  { label: "Signed in",     icon: "unlock", ink: "text-emerald-300", ring: "border-emerald-400/30 bg-emerald-950/40" },
  SSH_LOGOUT: { label: "Signed out",    icon: "logout", ink: "text-slate-300",   ring: "border-slate-400/25 bg-slate-900/40" },
  SSH_FAILED: { label: "Failed sign-in", icon: "lock",  ink: "text-amber-300",   ring: "border-amber-400/30 bg-amber-950/40" },
};

export function VpsAccessPanel({ events, agentSeen }: {
  events: AccessEvent[];
  /** Whether this server has ever reported telemetry at all. */
  agentSeen: boolean;
}) {
  if (!agentSeen) {
    return (
      <div className="card card-glass px-6 py-12 text-center">
        <span className="mx-auto grid h-[46px] w-[46px] place-items-center rounded-[14px] border border-rim-hi bg-well">
          <Icon name="shield2" size={20} />
        </span>
        <p className="mt-3.5 text-[15px] font-extrabold text-tx">No access history for this server</p>
        <p className="mx-auto mt-1.5 max-w-[48ch] text-[13px] leading-relaxed text-tx-dim">
          Sign-in history comes from the monitoring agent running on the server. This one has not
          reported any, so there is nothing to show — not an absence of logins.
        </p>
      </div>
    );
  }

  return (
    <div className="card card-glass p-4 sm:p-5">
      <div className="mb-3.5">
        <h2 className="text-[14.5px] font-extrabold text-tx">SSH access</h2>
        <p className="mt-0.5 text-[12px] text-tx-faint">
          Sign-ins and failed attempts reported by the agent on this server.
        </p>
      </div>

      {events.length === 0 ? (
        <p className="py-6 text-center text-[13px] text-tx-dim">
          The agent is reporting, but no sign-ins have been recorded in the retained window.
        </p>
      ) : (
        <ul className="flex flex-col divide-y divide-rim-soft">
          {events.map((e) => {
            const k = KIND[e.type] ?? { label: e.type, icon: "activity", ink: "text-slate-300", ring: "border-slate-400/25 bg-slate-900/40" };
            return (
              <li key={e.id} className="flex flex-wrap items-center gap-x-3 gap-y-1.5 py-2.5">
                <span className={`inline-flex flex-none items-center gap-1.5 rounded-full border px-2 py-1 text-[11px] font-bold ${k.ring} ${k.ink}`}>
                  <Icon name={k.icon} size={12} tone="inherit" />
                  {k.label}
                </span>
                {e.user && <span className="mono text-[12px] text-tx">{e.user}</span>}
                {e.ip && <span className="mono text-[12px] text-tx-dim">from {e.ip}</span>}
                <span className="ml-auto text-[11.5px] text-tx-faint">
                  {new Date(e.ts).toLocaleString()}
                </span>
              </li>
            );
          })}
        </ul>
      )}
    </div>
  );
}

