191	 */
192	/** One connection attempt with a given auth option; rejects on failure or timeout. */
193	function connectOnce(
194	  target: { host: string; port: number },
195	  auth: { privateKey: string } | { password: string }
196	): Promise<Client> {
197	  const conn = new Client();
198	  return new Promise<Client>((resolve, reject) => {
199	    const timer = setTimeout(() => {
200	      try {
201	        conn.end();
202	      } catch {
203	        /* best effort */
204	      }
205	      reject(new Error(`SSH connect timed out after ${Math.round(SSH_CONNECT_TIMEOUT_MS / 1000)}s`));
206	    }, SSH_CONNECT_TIMEOUT_MS);
207	    conn
208	      .on("ready", () => {
209	        clearTimeout(timer);
210	        resolve(conn);
211	      })
212	      .on("error", (e) => {
213	        clearTimeout(timer);
214	        reject(e instanceof Error ? e : new Error(String(e)));
215	      })
216	      .connect({
217	        host: target.host,
218	        port: target.port,
219	        username: "root",
220	        readyTimeout: SSH_CONNECT_TIMEOUT_MS,
221	        ...auth,
222	      });
223	  });
