219	/**
220	 * One-shot claim on `key`, valid for `ttlMs`. True the first time, false every
221	 * time after. Built on the same window store, so it inherits the same
222	 * single-process caveat documented at the top of this file.
223	 *
224	 * Used to make a TOTP code single-use (see lib/totp-verify.ts).
225	 */
226	export function claimOnce(key: string, ttlMs: number): boolean {
227	  return checkRateLimit(`once:${key}`, { max: 1, windowMs: ttlMs }).ok;
228	}
