20	function sandboxRrdSeries(maxMemBytes: number) {
21	  const now = Math.floor(Date.now() / 1000);
22	  const points = 70;
23	  const stepSeconds = 60;
24	  const out: { time: number; cpu: number; mem: number; maxmem: number }[] = [];
25	  for (let i = points - 1; i >= 0; i--) {
26	    const t = now - i * stepSeconds;
27	    const wobble = Math.sin(i / 6) * 0.05 + Math.sin(i / 19) * 0.03;
28	    const cpu = Math.max(0.02, Math.min(0.65, 0.16 + wobble));
29	    const memRatio = Math.max(0.25, Math.min(0.85, 0.52 + Math.sin(i / 14) * 0.08));
30	    out.push({ time: t, cpu, mem: Math.round(maxMemBytes * memRatio), maxmem: maxMemBytes });
31	  }
32	  return out;
33	}
