"use client";

import { WebsitesPanel } from "@/components/customer/cpanel/WebsitesPanel";
import { DatabasesPanel } from "@/components/customer/cpanel/DatabasesPanel";
import { AppsPanel } from "@/components/customer/cpanel/AppsPanel";
import { CronServicesPanel } from "@/components/customer/cpanel/CronServicesPanel";
import { SubNav, type SubSection } from "./ui";

/**
 * Services — what is running INSIDE the guest, as opposed to what the
 * hypervisor can see about the machine from outside.
 *
 * Same four panels the old Control panel had, moved off their own row of pills
 * and onto the side rail every other sub-sectioned tab in this panel uses.
 *
 * Nothing about CPU, memory or disk appears here any more. Those readings are
 * taken inside the guest and used to sit a few pixels from the hypervisor's
 * own numbers on Overview and in the Metrics tab, giving three figures for one
 * question that could not agree. The in-guest view keeps only what the
 * hypervisor genuinely cannot see.
 */

type Key = "websites" | "databases" | "apps" | "runtime";

const SECTIONS: SubSection<Key>[] = [
  { key: "websites",  label: "Websites",  sub: "Vhosts and certificates", icon: "globe2" },
  { key: "databases", label: "Databases", sub: "MySQL and Postgres",      icon: "database" },
  { key: "apps",      label: "Apps",      sub: "One-click installs",      icon: "cube" },
  { key: "runtime",   label: "Services",  sub: "Daemons and cron",        icon: "sliders" },
];

export function VpsServicesPanel({ serverId, running }: { serverId: string; running: boolean }) {
  if (!running) {
    return (
      <div className="card card-glass px-6 py-14 text-center">
        <p className="text-[15px] font-extrabold text-tx">The server isn&apos;t running</p>
        <p className="mx-auto mt-1.5 max-w-[46ch] text-[13px] leading-relaxed text-tx-dim">
          Everything on this tab is read over SSH from inside the machine, so it needs the server to
          be up. Start it and these come back.
        </p>
      </div>
    );
  }

  return (
    <SubNav
      sections={SECTIONS}
      slots={{
        websites: <WebsitesPanel serverId={serverId} running={running} />,
        databases: <DatabasesPanel serverId={serverId} running={running} />,
        apps: <AppsPanel serverId={serverId} running={running} />,
        runtime: <CronServicesPanel serverId={serverId} running={running} />,
      }}
    />
  );
}

