"use server";

import type { Client } from "ssh2";
import { db } from "./db";
import { requireUser } from "./auth";
import { checkRateLimit } from "./rate-limit";
import { SANDBOX } from "./sandbox";
import { withServerSsh, exec, QUICK_TIMEOUT_MS } from "./ssh-exec";
import type { SftpServer } from "./sftp";

/**
 * Read-only VPS system log — the "Activity → System log" sub-section of the
 * customer VPS panel (components/customer/vpspanel/v2/VpsSystemLog.tsx).
 *
 * Unlike the game control panel's `getGameLogs` (lib/game-control.ts), which
 * tails a specific game service's unit/log file, this reads the GUEST OS's own
 * general log — there is no per-service unit to target on a plain VPS. The
 * remote command is a FIXED, hardcoded, read-only string — never anything
 * derived from user input — reusing the exact `withServerSsh`/`exec` transport
 * every other inline SSH read in this repo already uses (lib/game-control.ts,
 * lib/cpanel-inline.ts) rather than inventing a new SSH client.
 *
 * No new storage: this is a live read of whatever the guest OS itself is
 * currently retaining in its own journal/log files. Nxeon keeps no independent
 * copy, so how far back it reaches depends on the server's own log
 * retention/rotation — not on us. `journalctl` is tried first (covers a
 * running system generally); `/var/log/cloud-init-output.log` is the fallback
 * for a minimal image where the systemd journal has nothing (e.g. a fresh
 * image whose journal is volatile and the box hasn't been up long).
 */

const MAX_LINES = 500;

async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({
    where: { id: serverId },
    select: {
      id: true,
      userId: true,
      status: true,
      vmid: true,
      hostname: true,
      rootPassword: true,
      rootPasswordEnc: true,
      sshManagementKeyEnc: true,
      sshPort: true,
      dedicatedIp: { select: { address: true } },
      node: { select: { publicIp: true } },
    },
  });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

/** 20 reads/minute/user — a live-tail poll every few seconds plus the occasional
 *  manual refresh, without letting one account hammer a box's SSH daemon. */
function throttle(userId: string): string | null {
  const rl = checkRateLimit(`vpslog:${userId}`, { max: 20, windowMs: 60_000 });
  return rl.ok ? null : `Too many requests — retry in ${rl.retryAfterSec}s.`;
}

type LogSource = "journal" | "cloud-init";

/** Marker-delimited single round trip: journal first, cloud-init log as fallback. */
async function readSystemLog(conn: Client, n: number): Promise<{ lines: string[]; source: LogSource | null }> {
  const lim = Math.min(Math.max(Math.trunc(n) || 300, 50), MAX_LINES);
  const script = [
    `echo "NXVPSLOG:JOURNAL"`,
    `journalctl -n ${lim} --no-pager -o short-iso 2>/dev/null`,
    `echo "NXVPSLOG:CLOUDINIT"`,
    `tail -n ${lim} /var/log/cloud-init-output.log 2>/dev/null`,
  ].join("\n");
  const { stdout } = await exec(conn, script, QUICK_TIMEOUT_MS);

  let section: LogSource | null = null;
  const journal: string[] = [];
  const cloudInit: string[] = [];
  for (const l of stdout.split(/\r?\n/)) {
    if (l === "NXVPSLOG:JOURNAL") { section = "journal"; continue; }
    if (l === "NXVPSLOG:CLOUDINIT") { section = "cloud-init"; continue; }
    if (section === "journal") journal.push(l);
    else if (section === "cloud-init") cloudInit.push(l);
  }
  const trimTrailingBlank = (arr: string[]) => {
    while (arr.length && arr[arr.length - 1].trim() === "") arr.pop();
    return arr;
  };
  trimTrailingBlank(journal);
  trimTrailingBlank(cloudInit);

  if (journal.length) return { lines: journal.slice(-lim), source: "journal" };
  if (cloudInit.length) return { lines: cloudInit.slice(-lim), source: "cloud-init" };
  return { lines: [], source: null };
}

export type VpsLogResult =
  | { ok: true; lines: string[]; source: LogSource }
  | { ok: false; error: string; unavailable?: boolean };

export async function getVpsSystemLog(serverId: string): Promise<VpsLogResult> {
  try {
    const { user, server } = await ownedServer(serverId);
    const limited = throttle(user.id);
    if (limited) return { ok: false, error: limited };

    // Not provisioned yet — the metrics API's own "not found vs. not ready"
    // distinction (app/api/metrics/route.ts): a real, owned server with no
    // vmid yet is not an error, it's just nothing to show yet.
    if (!server.vmid) {
      return { ok: false, unavailable: true, error: "This server hasn't finished provisioning yet." };
    }

    if (SANDBOX) {
      const now = new Date().toISOString();
      return {
        ok: true,
        source: "cloud-init",
        lines: [
          `${now} Cloud-init v. 24.4 running 'init-local'`,
          `${now} ci-info: no real hypervisor was contacted — sandbox synthetic log`,
          `${now} Cloud-init v. 24.4 finished. Datasource DataSourceNoCloud. Up 6.2 seconds`,
        ],
      };
    }

    if (server.status !== "RUNNING") {
      return { ok: false, unavailable: true, error: "Server is stopped — start it to view the live system log." };
    }

    const { lines, source } = await withServerSsh(server as SftpServer, (conn) => readSystemLog(conn, MAX_LINES));
    if (!source) {
      return { ok: false, unavailable: true, error: "No log output was returned by the server." };
    }
    return { ok: true, lines, source };
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    if (msg === "Not found" || msg === "Forbidden") return { ok: false, error: "Server not found." };
    // Unreachable/booting is a calm empty state, not a red error — same spirit
    // as the metrics endpoint's `{data: [], unavailable: true}`.
    return {
      ok: false,
      unavailable: true,
      error: "Could not reach the server for a live log right now — it may still be booting or restarting.",
    };
  }
}

