"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Icon } from "@/components/nx/Icon";
import { getVpsSystemLog } from "@/lib/actions-vps-logs";

/**
 * A bounded, read-only tail of the VPS's own system log — the VPS-panel
 * counterpart to the game panel's `GameConsole` live tail, but with no
 * command line: a VPS has no single game process to send RCON at, so this is
 * view-only (search/filter, auto-scroll, download), sourced from a fixed
 * `journalctl` (falling back to cloud-init's own output log) read over the
 * same SSH transport the game console and the file manager already use.
 *
 * Same 6s poll cadence as GameConsole, so a customer flipping between a game
 * server's console and a VPS's system log sees the same live-tail rhythm.
 */
export function VpsSystemLog({ serverId, running }: { serverId: string; running: boolean }) {
  const [lines, setLines] = useState<string[]>([]);
  const [source, setSource] = useState<"journal" | "cloud-init" | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [unavailable, setUnavailable] = useState(false);
  const [loaded, setLoaded] = useState(false);
  const [query, setQuery] = useState("");
  const [autoScroll, setAutoScroll] = useState(true);
  const box = useRef<HTMLDivElement>(null);

  const refresh = useCallback(() => {
    getVpsSystemLog(serverId).then((r) => {
      setLoaded(true);
      if (r.ok) {
        setLines(r.lines);
        setSource(r.source);
        setErr(null);
        setUnavailable(false);
      } else {
        setErr(r.error);
        setUnavailable(!!r.unavailable);
      }
    });
  }, [serverId]);

  useEffect(() => {
    if (!running) return;
    refresh();
    const t = setInterval(refresh, 6000);
    return () => clearInterval(t);
  }, [running, refresh]);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return lines;
    return lines.filter((l) => l.toLowerCase().includes(q));
  }, [lines, query]);

  useEffect(() => {
    if (autoScroll && box.current) box.current.scrollTop = box.current.scrollHeight;
  }, [filtered, autoScroll]);

  function download() {
    const blob = new Blob([lines.join("\n")], { type: "text/plain" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `system-log-${serverId}-${new Date().toISOString().slice(0, 19).replace(/[:T]/g, "-")}.log`;
    a.click();
    URL.revokeObjectURL(url);
  }

  if (!running) {
    return (
      <div className="card card-glass px-6 py-14 text-center">
        <p className="text-[15px] font-extrabold text-tx">The server isn&apos;t running</p>
        <p className="mx-auto mt-1.5 max-w-[46ch] text-[13px] leading-relaxed text-tx-dim">
          The system log is read live over SSH from inside the machine, so it needs the server to be
          up. Start it and this comes back.
        </p>
      </div>
    );
  }

  if (loaded && unavailable && lines.length === 0) {
    return (
      <div className="card card-glass px-6 py-12 text-center">
        <span className="mx-auto grid h-[46px] w-[46px] place-items-center rounded-[14px] border border-rim-hi bg-well">
          <Icon name="filesearch" size={20} />
        </span>
        <p className="mt-3.5 text-[15px] font-extrabold text-tx">No live log available right now</p>
        <p className="mx-auto mt-1.5 max-w-[48ch] text-[13px] leading-relaxed text-tx-dim">
          {err ?? "The server couldn't be reached for a live log."}
        </p>
      </div>
    );
  }

  return (
    <section className="nx-dark-island flex min-w-0 flex-col overflow-hidden rounded-[16px] border border-rim-hi bg-[rgba(3,9,24,.88)]">
      <div className="flex flex-wrap items-center gap-2.5 border-b border-rim-soft px-4 py-2.5">
        <h3 className="text-[13.5px] font-extrabold text-white">System log</h3>
        <span className="flex items-center gap-1.5 text-[11.5px] font-semibold text-emerald-400">
          <span className="h-[6px] w-[6px] animate-pulse rounded-full bg-emerald-400" />
          Tailing
        </span>
        {source && (
          <span className="rounded-full border border-rim-hi px-2 py-0.5 text-[10.5px] font-bold uppercase tracking-wide text-tx-faint">
            {source === "journal" ? "journalctl" : "cloud-init"}
          </span>
        )}

        <span className="ml-auto flex h-[32px] w-[180px] items-center gap-2 rounded-[9px] border border-rim-hi bg-well px-3">
          <Icon name="search" size={13} tone="inherit" className="flex-none text-tx-faint" />
          <input
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Filter…"
            className="min-w-0 flex-1 bg-transparent text-[12px] text-white outline-none placeholder:text-tx-faint"
          />
        </span>
        <button
          type="button"
          onClick={() => setAutoScroll((v) => !v)}
          aria-pressed={autoScroll}
          className={"rounded-[9px] border px-3 py-1.5 text-[12px] font-semibold transition " +
            (autoScroll ? "border-[#8b5cff]/60 bg-[#7b3fef]/20 text-white" : "border-rim-hi text-tx-dim hover:text-white")}
        >
          Auto-scroll
        </button>
        <button type="button" onClick={download} disabled={lines.length === 0}
                className="rounded-[9px] border border-rim-hi px-3 py-1.5 text-[12px] font-semibold text-tx-dim transition hover:text-white disabled:opacity-40">
          Download
        </button>
      </div>

      <div ref={box} className="max-h-[520px] min-h-[300px] overflow-auto px-4 py-3 font-mono text-[12px] leading-[1.75]">
        {!loaded ? (
          <p className="text-tx-faint">Loading…</p>
        ) : filtered.length === 0 ? (
          <p className="text-tx-faint">{query ? `Nothing matches “${query}”.` : "No output yet."}</p>
        ) : (
          filtered.map((l, i) => <div key={i} className="text-tx-dim">{l}</div>)
        )}
      </div>

      <div className="border-t border-rim-soft px-4 py-2.5">
        <p className="text-[12px] leading-relaxed text-tx-faint">
          A live read of this server&apos;s own log — Nxeon keeps no separate copy, so how far back it
          reaches depends on the server&apos;s own retention.
        </p>
        {err && !unavailable && <p className="mt-1 text-[12px] text-amber-300">{err}</p>}
      </div>
    </section>
  );
}

