/**
 * `n` defaults to 200 (the live-tail view's usual page size). Callers that want
 * more history for a one-off "download the full log" — e.g. after a crash,
 * where the interesting line scrolled out of the live view minutes ago — can
 * ask for up to readGameLogs's own cap of 500; it is clamped there regardless
 * of what is passed. A separate, tighter rate-limit bucket applies to that
 * larger pull so a "download full log" click can't be used to hammer the SSH
 * connection at the same 40/min rate the small live-tail poll gets.
 */
export async function getGameLogs(
  serverId: string,
  n?: number
): Promise<{ ok: true; lines: string[]; unit: string | null } | { ok: false; error: string }> {
  try {
    const { user, server } = await ownedServer(serverId);
    const spec = requireSpec(server);
    const wantsFull = typeof n === "number" && n > 200;
    const limited = wantsFull ? throttle(user.id, "logs-full", 6) : throttle(user.id, "logs", 40);
    if (limited) return { ok: false, error: limited };
    if (SANDBOX) {
      return {
        ok: true,
        unit: spec.serviceHints[0],
        lines: [
          `[${new Date().toISOString()}] [Server thread/INFO]: Starting ${spec.label} server`,
          `[${new Date().toISOString()}] [Server thread/INFO]: Loading world`,
          `[${new Date().toISOString()}] [Server thread/INFO]: Done — sandbox synthetic log (no VM was contacted).`,
        ],
      };
    }
    if (server.status !== "RUNNING")
      return { ok: false, error: "Logs are available only while the server is running." };
    const res = await withServerSsh(server as SftpServer, (conn) => readGameLogs(conn, spec, n));
    return res.ok ? { ok: true, lines: res.lines, unit: res.unit } : { ok: false, error: res.error };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

