// Temporary, local-only verification script — NOT committed. Mints a session
// cookie the same way lib/auth.ts's createSession() does (same JWT shape/
// secret, read from process.env — never a literal in this file) so we can
// screenshot the dashboard as a real logged-in user without needing to type a
// password anywhere.
import { readFileSync } from "node:fs";
import { SignJWT } from "jose";
import { chromium } from "playwright";
import pg from "pg";

// --- load .env (KEY=VALUE, ignore comments/blank lines) --------------------
const envText = readFileSync(new URL("./.env", import.meta.url), "utf8");
for (const line of envText.split("\n")) {
  const m = /^([A-Za-z_][A-Za-z0-9_]*)=(.*)$/.exec(line.trim());
  if (m && !(m[1] in process.env)) process.env[m[1]] = m[2];
}

const BASE = "http://localhost:3036";
const OUT = "/tmp/claude-0/-root/ec6fa978-d80b-4147-9982-eea470598e2c/scratchpad/logs-ui";
const COOKIE_NAME = process.env.NXEON_COOKIE_NAME ?? "nxeon_session";
const secret = new TextEncoder().encode(process.env.AUTH_SECRET);

const client = new pg.Client({ connectionString: process.env.DATABASE_URL });
await client.connect();
const { rows } = await client.query(
  `select id, "sessionVersion" from "User" where email = $1`,
  ["admin@nxeon.local"]
);
await client.end();
